export async function registerOffline(){if(globalThis.Capacitor?.isNativePlatform?.())return null;if(!('serviceWorker'in navigator))return null;try{return await navigator.serviceWorker.register('./sw.js');}catch{return null;}}
export async function downloadOffline(sex,onProgress){
 if(globalThis.Capacitor?.isNativePlatform?.()){if(!['male','female','volume'].includes(sex))throw Error('Geçersiz model');const response=await fetch('./offline-assets.json');if(!response.ok)throw Error('Yerel model listesi okunamadı');const files=(await response.json())[sex];onProgress?.(files.length,files.length);return {type:'done',sex,native:true};}
 const registration=await registerOffline();if(!registration)throw Error('Bu tarayıcı çevrimdışı kaydı desteklemiyor.');
 let timer;try{await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Çevrimdışı hazırlık tamamlanamadı. Bağlantını kontrol edip tekrar dene.')),15000);})]);}finally{clearTimeout(timer);}
 const worker=registration.active||navigator.serviceWorker.controller;if(!worker)throw Error('Sayfayı bir kez yenileyip tekrar dene.');
 return new Promise((resolve,reject)=>{const channel=new MessageChannel();let timeout;const finish=(err,value)=>{clearTimeout(timeout);channel.port1.close();err?reject(err):resolve(value);};const keepAlive=()=>{clearTimeout(timeout);timeout=setTimeout(()=>finish(Error('İndirme yanıtı gelmedi. Tekrar dene; tamamlanmış dosyalar korunur.')),180000);};keepAlive();channel.port1.onmessage=e=>{const d=e.data;keepAlive();if(d.type==='progress')onProgress(d.done,d.total);if(d.type==='done')finish(null,d);if(d.type==='error')finish(Error(d.message));};channel.port1.onmessageerror=()=>finish(Error('İndirme yanıtı okunamadı.'));try{worker.postMessage({type:'download',sex},[channel.port2]);}catch(e){finish(e);}});
}
